1	/**
2	 * Pure hauler movement kinematics — P2 subset (run / jump / air-steer /
3	 * gravity / AABB vs solid grid). No treasure, traps, encumbrance, or
4	 * surface-friction variants yet.
5	 *
6	 * KEEP IN SYNC with client/src/net/kinematics.ts (verbatim copy for
7	 * prediction parity, per netcode-client DESIGN §8.1 / §16 — extraction into
8	 * a shared package is a P3+ cleanup). This file must stay dependency-free.
9	 *
10	 * Coordinates: world pixels, y-down (docs/interfaces/level-format.md).
11	 * Fixed timestep only — dt comes from config, never wall clock.
12	 */
13	
14	/** All tunable movement constants live here (simulation DESIGN §5.2). */
15	export interface KinematicsConfig {
16	  /** Fixed physics timestep in seconds (1 / tickRate). */
17	  dt: number;
18	  /** Hauler AABB half extents in px. */
19	  halfW: number;
20	  halfH: number;
21	  /** Ground run acceleration px/s². */
22	  runAccel: number;
23	  /** Airborne steer acceleration px/s² (reduced vs ground). */
24	  airAccel: number;
25	  /** Ground deceleration toward 0 when no input, px/s². */
26	  groundFriction: number;
27	  /** Max horizontal speed px/s. */
28	  maxSpeed: number;
29	  /** Gravity px/s² (positive = down). */
30	  gravity: number;
31	  /** Terminal fall speed px/s. */
32	  maxFallSpeed: number;
33	  /** Upward jump impulse magnitude px/s. */
34	  jumpSpeed: number;
35	  /** Jump input buffered for this many steps while airborne. */
36	  jumpBufferSteps: number;
37	}
38	
39	export const DEFAULT_KINEMATICS: KinematicsConfig = {
40	  dt: 1 / 30,
41	  halfW: 12,
42	  halfH: 14,
43	  runAccel: 1400,
44	  airAccel: 700,
45	  groundFriction: 1800,
46	  maxSpeed: 160,
47	  gravity: 1500,
48	  maxFallSpeed: 540,
49	  jumpSpeed: 430,
50	  jumpBufferSteps: 3,
51	};
52	
53	/** Mutable hauler body state advanced by {@link stepHauler}. */
54	export interface HaulerBody {
55	  x: number;
56	  y: number;
57	  vx: number;
58	  vy: number;
59	  grounded: boolean;
60	  facing: 1 | -1;
61	  /** Previous step's jump level, for edge detection. */
62	  jumpHeld: boolean;
63	  /** Remaining buffered-jump steps (0 = none pending). */
64	  jumpBuffer: number;
65	}
66	
67	export function createBody(x: number, y: number): HaulerBody {
68	  return {
69	    x,
70	    y,
71	    vx: 0,
