1	/**
2	 * C07-T08/T09 — rollTreasureDef: world rolls + chest open tables (DESIGN §6.6).
3	 *
4	 * Constraints (design-locked):
5	 * 1. Never roll a unique/set def listed in `ctx.excludedDefIds` (live in play).
6	 * 2. Chests never open into other chests.
7	 * 3. Magic chest prefers the missing piece of an almost-complete set.
8	 * 4. Revealed items use their `baseValueGp` (no separate chest GP).
9	 *
10	 * Fallback policy (implementation-locked, deterministic): if a table's pool is
11	 * empty after exclusions, fall back unique → rare → common (non-chest); the
12	 * common pool is never empty.
13	 */
14	import type { LootTableId, RollContext, TreasureDef } from "../types.js";
15	import type { Rng } from "../rng/types.js";
16	import { TREASURE_DEFS } from "./catalog.js";
17	import { rarityForRoll } from "./rarity.js";
18	
19	function notExcluded(ctx: RollContext) {
20	  const excluded = new Set(ctx.excludedDefIds ?? []);
21	  return (d: TreasureDef) => !excluded.has(d.id);
22	}
23	
24	function pool(
25	  rarities: readonly string[],
26	  ctx: RollContext,
27	  opts: { allowChests?: boolean } = {},
28	): TreasureDef[] {
29	  const allowed = notExcluded(ctx);
30	  return TREASURE_DEFS.filter(
31	    (d) =>
32	      rarities.includes(d.rarity) &&
33	      (opts.allowChests === true || !d.isChest) &&
34	      // Exclusions only meaningfully target uniques/set pieces, but honoring
35	      // them for any listed id is harmless and simpler.
36	      allowed(d),
37	  );
38	}
39	
40	function pickUniform(rng: Rng, defs: readonly TreasureDef[]): TreasureDef {
41	  const picked = defs[rng.nextInt(defs.length)];
42	  if (!picked) {
43	    throw new Error("rollTreasureDef: empty pool (catalog invariant broken)");
44	  }
45	  return picked;
46	}
47	
48	function firstNonEmpty(pools: readonly TreasureDef[][]): TreasureDef[] {
49	  for (const p of pools) if (p.length > 0) return p;
50	  throw new Error("rollTreasureDef: all fallback pools empty");
51	}
52	
53	function rollWorld(rng: Rng, ctx: RollContext): TreasureDef {
54	  const band = rarityForRoll(rng.nextInt(100));
55	  // World rolls may produce chest shells (chests are common/rare entries).
56	  const bandPool = pool([band], ctx, { allowChests: true });
57	  const chosen = firstNonEmpty([
58	    bandPool,
59	    pool(["common"], ctx, { allowChests: true }),
60	  ]);
61	  return pickUniform(rng, chosen);
62	}
63	
64	function rollMagic(rng: Rng, ctx: RollContext): TreasureDef {
65	  // Prefer the last missing piece of any almost-complete set.
66	  const excluded = new Set(ctx.excludedDefIds ?? []);
67	  const missing = (ctx.almostCompleteSets ?? [])
68	    .map((s) => s.missingDefId)
69	    .filter((id) => !excluded.has(id))
70	    .map((id) => TREASURE_DEFS.find((d) => d.id === id))
71	    .filter((d): d is TreasureDef => d !== undefined);
72	  if (missing.length > 0) return pickUniform(rng, missing);
73	  const chosen = firstNonEmpty([
74	    pool(["unique"], ctx),
75	    pool(["rare"], ctx),
76	    pool(["common"], ctx),
77	  ]);
78	  return pickUniform(rng, chosen);
79	}
80	
81	export function rollTreasureDef(
82	  rng: Rng,
83	  table: LootTableId,
84	  ctx: RollContext = {},
85	): TreasureDef {
86	  switch (table) {
87	    case "world":
88	      return rollWorld(rng, ctx);
89	    case "wooden_chest":
90	      return pickUniform(
91	        rng,
92	        firstNonEmpty([pool(["common", "rare"], ctx), pool(["common"], ctx)]),
93	      );
94	    case "silver_chest":
95	      return pickUniform(
96	        rng,
97	        firstNonEmpty([
98	          pool(["common", "rare", "unique"], ctx),
99	          pool(["common"], ctx),
100	        ]),
101	      );
102	    case "gold_chest":
103	      return pickUniform(
104	        rng,
105	        firstNonEmpty([
106	          pool(["rare", "unique", "set"], ctx),
107	          pool(["rare"], ctx),
108	          pool(["common"], ctx),
109	        ]),
110	      );
111	    case "magic_chest":
112	      return rollMagic(rng, ctx);
113	  }
114	}
