1	/**
2	 * HaulSession — Colyseus room hosting the authoritative movement sim (P2).
3	 *
4	 * Transport adaptation (see @dhaul/protocol codec.ts module doc): the
5	 * C2S_Join handshake travels as Colyseus join options; join rejection uses
6	 * ServerError with COLYSEUS_ERROR_CODES; every other message is sent on a
7	 * channel named by its wire `type` with the full contract message object as
8	 * payload. State sync uses plain JSON snapshot broadcasts each tick (no
9	 * Colyseus schema) — full WorldSnapshot per contract, 4 haulers is tiny.
10	 */
11	
12	import { CloseCode, Room, ServerError, type Client } from "@colyseus/core";
13	import {
14	  COLYSEUS_ERROR_CODES,
15	  isC2SInput,
16	  isJoinOptions,
17	  protocolVersion,
18	  type GameEvent,
19	  type S2C_Error,
20	  type S2C_Pong,
21	  type S2C_SeatUpdate,
22	  type S2C_Snapshot,
23	  type S2C_Welcome,
24	  type SeatId,
25	} from "@dhaul/protocol";
26	import { getLevel, P2_LEVEL_ID } from "../content.js";
27	import type { LobbyService } from "../lobby/service.js";
28	import { DEFAULT_SIM_CONFIG } from "../sim/config.js";
29	import { Simulation } from "../sim/simulation.js";
30	
31	/** Injected process-wide deps (rooms are constructed by Colyseus). */
32	interface RoomDeps {
33	  lobby: LobbyService;
34	}
35	
36	let deps: RoomDeps | undefined;
37	
38	export function setHaulSessionDeps(d: RoomDeps): void {
39	  deps = d;
40	}
41	
42	interface ClientMeta {
43	  seatId: SeatId;
44	  /** Token bucket for input rate limiting (~tickRate * 2). */
45	  tokens: number;
46	  lastRefillMs: number;
47	}
48	
49	const TICK_MS = 1000 / DEFAULT_SIM_CONFIG.tickRate;
50	const INPUT_RATE_LIMIT_PER_SEC = DEFAULT_SIM_CONFIG.tickRate * 2;
51	const TICK_LAG_LOG_EVERY = 150; // ~5s at 30 Hz
52	
53	export class HaulSession extends Room {
54	  private sim!: Simulation;
55	  private startedAtMs = 0;
56	  private readonly meta = new Map<string, ClientMeta>();
57	
58	  private get lobby(): LobbyService {
59	    if (!deps) throw new Error("HaulSession deps not initialised");
60	    return deps.lobby;
61	  }
62	
63	  override onCreate(): void {
64	    this.maxClients = 4;
65	    this.autoDispose = false; // lobby owns lifecycle (created before first WS join)
66	    this.sim = new Simulation(getLevel(P2_LEVEL_ID), DEFAULT_SIM_CONFIG);
67	    this.startedAtMs = Date.now();
68	
69	    this.onMessage("input", (client, payload: unknown) => this.handleInput(client, payload));
70	    this.onMessage("ping", (client, payload: unknown) => {
71	      const clientTime =
72	        typeof payload === "object" && payload !== null
73	          ? Number((payload as { clientTime?: unknown }).clientTime ?? 0)
74	          : 0;
75	      const pong: S2C_Pong = { type: "pong", clientTime, serverTime: Date.now() };
76	      client.send("pong", pong);
77	    });
78	    this.onMessage("leave", (client) => {
79	      client.leave(CloseCode.CONSENTED);
80	    });
81	    // Forward-compatibility: ignore unknown channels silently.
82	    this.onMessage("*", () => undefined);
83	
84	    this.setSimulationInterval(() => this.tick(), TICK_MS);
85	  }
86	
87	  /** roomId doubles as the contract sessionId (see lobby service). */
88	  private get sessionId(): string {
89	    return this.roomId;
90	  }
91	
92	  override onJoin(client: Client, options: unknown): void {
93	    if (!isJoinOptions(options)) {
94	      throw new ServerError(COLYSEUS_ERROR_CODES.PROTOCOL, "malformed join options");
95	    }
96	    if (options.protocolVersion !== protocolVersion) {
97	      throw new ServerError(
98	        COLYSEUS_ERROR_CODES.PROTOCOL,
99	        `protocol mismatch: server=${protocolVersion} client=${options.protocolVersion}`,
100	      );
101	    }
102	    if (options.sessionId !== this.sessionId) {
103	      throw new ServerError(COLYSEUS_ERROR_CODES.AUTH, "wrong session");
104	    }
105	    const seatId = this.lobby.verifySeatToken(this.sessionId, options.seatToken);
106	    if (seatId === null) {
107	      throw new ServerError(COLYSEUS_ERROR_CODES.AUTH, "invalid seat token");
108	    }
109	    if (
110	      options.reconnectToken !== undefined &&
111	      !this.lobby.verifyReconnectToken(this.sessionId, seatId, options.reconnectToken)
112	    ) {
113	      throw new ServerError(COLYSEUS_ERROR_CODES.AUTH, "reconnect grace expired");
114	    }
115	    // One live connection per seat: a fresh valid join replaces a stale one.
116	    for (const [sid, m] of this.meta) {
117	      if (m.seatId === seatId && sid !== client.sessionId) {
118	        this.clients.find((c) => c.sessionId === sid)?.leave(CloseCode.CONSENTED);
119	        this.meta.delete(sid);
120	      }
121	    }
122	
123	    this.meta.set(client.sessionId, {
124	      seatId,
125	      tokens: INPUT_RATE_LIMIT_PER_SEC,
126	      lastRefillMs: Date.now(),
127	    });
128	    const session = this.lobby.getSession(this.sessionId);
129	    const displayName = session?.seats[seatId]?.displayName;
130	    const events = this.sim.bindHuman(seatId, client.sessionId, displayName);
131	    this.lobby.markConnected(this.sessionId, seatId);
132	
133	    const welcome: S2C_Welcome = {
134	      type: "welcome",
135	      protocolVersion,
136	      sessionId: this.sessionId,
137	      seatId,
138	      reconnectToken: this.lobby.rotateReconnectToken(this.sessionId, seatId),
139	      rngSeed: this.sim.config.rngSeed,
140	      rulesetVersion: this.sim.config.rulesetVersion,
141	      tickRate: 30,
142	      phase: "level",
143	      snapshot: this.sim.buildSnapshot(),
