1	import { beforeEach, describe, expect, it } from "vitest";
2	import { DEFAULT_SIM_CONFIG } from "../../src/sim/config.js";
3	import { boxLevel, cmd, makeSim, resetSeq, runTape } from "./helpers.js";
4	
5	const KIN = DEFAULT_SIM_CONFIG.kinematics;
6	// Box level: floor top at y = 5*32 = 160; resting body center ≈ 160 - halfH.
7	const FLOOR_TOP = 5 * 32;
8	const REST_Y = FLOOR_TOP - KIN.halfH;
9	
10	beforeEach(resetSeq);
11	
12	function hauler(snapshot: { haulers: { seatId: number }[] }, seatId: number) {
13	  const h = snapshot.haulers.find((x) => x.seatId === seatId);
14	  if (!h) throw new Error(`no hauler ${seatId}`);
15	  return h as (typeof snapshot.haulers)[number] & {
16	    x: number;
17	    y: number;
18	    vx: number;
19	    vy: number;
20	    facing: number;
21	    anim: string;
22	    control: string;
23	  };
24	}
25	
26	describe("sim: determinism", () => {
27	  it("identical input tapes produce identical positions", () => {
28	    const tape = () => {
29	      resetSeq();
30	      return [
31	        ...Array.from({ length: 10 }, () => cmd({ x: 1 })),
32	        ...Array.from({ length: 5 }, () => cmd({ x: 1, jump: true })),
33	        ...Array.from({ length: 15 }, () => cmd({ x: -1 })),
34	      ];
35	    };
36	    const a = makeSim();
37	    a.bindHuman(0, "h1");
38	    const snapsA = runTape(a, 0, tape());
39	
40	    const b = makeSim();
41	    b.bindHuman(0, "h1");
42	    const snapsB = runTape(b, 0, tape());
43	
44	    expect(snapsA.map((s) => hauler(s, 0))).toEqual(
45	      snapsB.map((s) => hauler(s, 0)),
46	    );
47	  });
48	
49	  it("settles onto the floor and never produces NaN", () => {
50	    const sim = makeSim();
51	    for (let i = 0; i < 60; i++) sim.step();
52	    const snap = sim.buildSnapshot();
53	    for (const h of snap.haulers) {
54	      expect(Number.isFinite(h.x) && Number.isFinite(h.y)).toBe(true);
55	      expect(h.y).toBeGreaterThan(REST_Y - 1);
56	      expect(h.y).toBeLessThan(REST_Y + 1);
57	      expect(h.anim).toBe("idle");
58	    }
59	  });
60	});
61	
62	describe("sim: run", () => {
63	  it("moves right under held input and faces the run direction", () => {
64	    const sim = makeSim();
65	    sim.bindHuman(0, "h1");
66	    const snaps = runTape(sim, 0, Array.from({ length: 30 }, () => cmd({ x: 1 })));
67	    const first = hauler(snaps[0]!, 0);
68	    const last = hauler(snaps.at(-1)!, 0);
69	    expect(last.x).toBeGreaterThan(first.x + 100);
70	    expect(last.facing).toBe(1);
71	    expect(Math.abs(last.vx)).toBeLessThanOrEqual(KIN.maxSpeed);
72	  });
73	
74	  it("stops against the left wall without penetrating it", () => {
75	    const sim = makeSim();
76	    sim.bindHuman(0, "h1");
77	    const snaps = runTape(sim, 0, Array.from({ length: 90 }, () => cmd({ x: -1 })));
78	    const last = hauler(snaps.at(-1)!, 0);
79	    // Left wall occupies cell 0 → inner face at x = 32; body min x = 32 + halfW.
80	    expect(last.x).toBeGreaterThanOrEqual(32 + KIN.halfW - 0.01);
81	    expect(last.x).toBeLessThan(32 + KIN.halfW + 1);
82	    expect(last.vx).toBe(0);
83	  });
84	});
85	
86	describe("sim: jump", () => {
87	  it("jump edge triggers once per press cycle (held jump does not re-fire)", () => {
88	    const sim = makeSim();
89	    sim.bindHuman(0, "h1");
90	    // Settle.
91	    runTape(sim, 0, Array.from({ length: 20 }, () => cmd()));
92	    // Hold jump for 40 ticks: one launch, land, and stay grounded after.
93	    const snaps = runTape(
94	      sim,
95	      0,
96	      Array.from({ length: 40 }, () => cmd({ jump: true })),
97	    );
98	    const apex = Math.min(...snaps.map((s) => hauler(s, 0).y));
99	    expect(apex).toBeLessThan(REST_Y - 40); // actually left the ground
100	    const tail = snaps.slice(-5).map((s) => hauler(s, 0));
101	    for (const h of tail) {
102	      expect(h.y).toBeCloseTo(REST_Y, 0); // no re-jump while held
103	      expect(h.anim).toBe("idle");
104	    }
105	    // Release then press again → second jump fires.
106	    runTape(sim, 0, [cmd()]);
107	    const again = runTape(
108	      sim,
109	      0,
110	      Array.from({ length: 10 }, () => cmd({ jump: true })),
111	    );
112	    expect(Math.min(...again.map((s) => hauler(s, 0).y))).toBeLessThan(REST_Y - 20);
113	  });
114	
115	  it("air steer moves the hauler horizontally mid-jump", () => {
116	    const sim = makeSim();
117	    sim.bindHuman(0, "h1");
118	    runTape(sim, 0, Array.from({ length: 20 }, () => cmd())); // settle
119	    const x0 = hauler(sim.buildSnapshot(), 0).x;
120	    const snaps = runTape(sim, 0, [
121	      cmd({ jump: true }),
122	      ...Array.from({ length: 12 }, () => cmd({ x: 1, jump: true })),
123	    ]);
124	    const mid = snaps[8]!;
125	    expect(hauler(mid, 0).y).toBeLessThan(REST_Y - 10); // airborne
126	    expect(hauler(snaps.at(-1)!, 0).x).toBeGreaterThan(x0 + 20);
127	  });
128	});
129	
130	describe("sim: no tunneling", () => {
131	  it("a body dropped from far above the floor lands on it (fixed dt, capped fall)", () => {
132	    // Direct kinematics check at terminal velocity: worst case per-tick move is
133	    // maxFallSpeed * dt = 18px < blockSize; sub-stepping must still land.
134	    const sim = makeSim();
135	    // Teleport-free equivalent: run many ticks; the seats spawn airborne and
136	    // must come to rest exactly on the floor, never below it.
137	    let minY = Infinity;
138	    let maxY = -Infinity;
139	    for (let i = 0; i < 120; i++) {
140	      const { snapshot } = sim.step();
141	      for (const h of snapshot.haulers) {
142	        minY = Math.min(minY, h.y);
143	        maxY = Math.max(maxY, h.y);
144	      }
145	    }
146	    expect(maxY).toBeLessThanOrEqual(REST_Y + 0.5);
147	  });
148	
149	  it("kinematics config caps fall distance below one block per tick", () => {
150	    const bs = boxLevel().blockSizePx;
151	    expect((KIN.maxFallSpeed * KIN.dt)).toBeLessThan(bs);
152	  });
153	});
