1	/**
2	 * C-03 Input Mapper (P2 keyboard subset): arrows/WASD move, Z jump (A),
3	 * X action (B), Enter start. Produces the normalized InputCommand with a
4	 * per-seat monotonic seq (input-commands.md).
5	 */
6	
7	import type { AxisValue, InputCommand } from "@dhaul/protocol";
8	
9	const KEY_LEFT = new Set(["ArrowLeft", "KeyA"]);
10	const KEY_RIGHT = new Set(["ArrowRight", "KeyD"]);
11	const KEY_UP = new Set(["ArrowUp", "KeyW"]);
12	const KEY_DOWN = new Set(["ArrowDown", "KeyS"]);
13	const KEY_JUMP = new Set(["KeyZ", "Space"]);
14	const KEY_ACTION = new Set(["KeyX"]);
15	const KEY_START = new Set(["Enter"]);
16	
17	export class KeyboardInputMapper {
18	  private readonly down = new Set<string>();
19	  private seq = 0;
20	
21	  private readonly onKeyDown = (e: KeyboardEvent): void => {
22	    this.down.add(e.code);
23	  };
24	  private readonly onKeyUp = (e: KeyboardEvent): void => {
25	    this.down.delete(e.code);
26	  };
27	
28	  attach(target: Window): void {
29	    target.addEventListener("keydown", this.onKeyDown);
30	    target.addEventListener("keyup", this.onKeyUp);
31	    target.addEventListener("blur", () => this.down.clear());
32	  }
33	
34	  /** Reset seq coordination on (re)welcome (DESIGN §3.2). */
35	  resetSeq(): void {
36	    this.seq = 0;
37	  }
38	
39	  private axis(neg: Set<string>, pos: Set<string>): AxisValue {
40	    const n = [...neg].some((k) => this.down.has(k));
41	    const p = [...pos].some((k) => this.down.has(k));
42	    if (n === p) return 0;
43	    return p ? 1 : -1;
44	  }
45	
46	  private has(keys: Set<string>): boolean {
47	    return [...keys].some((k) => this.down.has(k));
48	  }
49	
50	  /** Sample current levels into a command (call once per send tick). */
51	  sample(): InputCommand {
52	    return {
53	      seq: ++this.seq,
54	      axes: {
55	        x: this.axis(KEY_LEFT, KEY_RIGHT),
56	        y: this.axis(KEY_UP, KEY_DOWN),
57	      },
58	      jump: this.has(KEY_JUMP),
59	      action: this.has(KEY_ACTION),
60	      start: this.has(KEY_START),
61	    };
62	  }
63	}
